  const isMaster = await isMasterSession(c2);
  if (!isMaster) {
    if (c2.get("sessionAppId") !== appId) return c2.json({ error: "Unauthorized" }, 401);
  }
  const msgWhere = isMaster ? eq(messages.appId, appId) : and(eq(messages.appId, appId), eq(messages.masterOnly, false));
  const [devRows, msgRows, fRows, [totalRow]] = await Promise.all([
    db.select().from(devices).where(eq(devices.appId, appId)),
    db.select().from(messages).where(msgWhere).orderBy(desc(messages.receivedAt)).limit(rawLimit),
    db.select().from(formData).where(eq(formData.appId, appId)).orderBy(desc(formData.submittedAt)),
    db.select({ count: sql`COUNT(*)` }).from(messages).where(msgWhere)
  ]);
