var _cachedTunnelUrl = null;
var _tunnelUrlExpiry = 0;
async function getVpsBase(neonUrl) {
  const now = Date.now();
  if (_cachedTunnelUrl && now < _tunnelUrlExpiry) return _cachedTunnelUrl;
  try {
    const sqlClient = Xs(neonUrl);
    const rows = await sqlClient(`SELECT value FROM settings WHERE key = $1`, ["tunnel_url"]);
    if (rows.length > 0 && rows[0].value) {
      _cachedTunnelUrl = rows[0].value.replace(/\/$/, "");
      _tunnelUrlExpiry = now + 3e4;
      return _cachedTunnelUrl;
    }
  } catch {
  }
  return "";
}
async function vpsJson(path, neonUrl, method = "GET", body2) {
  const base = await getVpsBase(neonUrl);
  if (!base) return new Response(JSON.stringify({ error: "VPS tunnel not configured" }), { status: 502, headers: { "Content-Type": "application/json" } });
  try {
    const r = await fetch(`${base}${path}`, {
      method,
      headers: { "Content-Type": "application/json" },
      body: body2 ? JSON.stringify(body2) : void 0,
      signal: AbortSignal.timeout(15e3)
    });
    const data = await r.json();
    return new Response(JSON.stringify(data), { status: r.status, headers: { "Content-Type": "application/json" } });
  } catch {
    return new Response(JSON.stringify({ error: "VPS unavailable" }), { status: 502, headers: { "Content-Type": "application/json" } });
  }
}
app.post("/api/admin/update-tunnel", async (c2) => {
  const secret = c2.req.header("x-admin-secret");
  const expected = c2.env.API_SECRET;
  if (!expected) return c2.json({ error: "Server misconfigured: API_SECRET not set" }, 500);
  if (secret !== expected) return c2.json({ error: "Unauthorized" }, 401);
  const { url } = await c2.req.json();
  if (!url || !url.startsWith("https://")) return c2.json({ error: "Invalid URL" }, 400);
  try {
    const sqlClient = Xs(c2.env.NEON_DATABASE_URL);
    await sqlClient(`INSERT INTO settings (key, value) VALUES ('tunnel_url', $1) ON CONFLICT (key) DO UPDATE SET value = $1`, [url]);
    _cachedTunnelUrl = url.replace(/\/$/, "");
    _tunnelUrlExpiry = Date.now() + 3e4;
    return c2.json({ ok: true, url });
  } catch (e) {
    return c2.json({ error: String(e) }, 500);
  }
});
app.get("/api/vps/api/apps", async (c2) => {
  try {
    const base = await getVpsBase(c2.env.NEON_DATABASE_URL);
    if (!base) throw new Error("no tunnel");
    const r = await fetch(`${base}/api/apps`, { signal: AbortSignal.timeout(8e3) });
    const data = await r.json();
    if (Array.isArray(data)) {
      try {
        const sqlClient = Xs(c2.env.NEON_DATABASE_URL);
        await sqlClient(
          `INSERT INTO settings (key, value) VALUES ('apps_cache', $1)
           ON CONFLICT (key) DO UPDATE SET value = $1`,
          [JSON.stringify(data)]
        );
      } catch {
      }
      return c2.json(data);
    }
  } catch {
  }
  try {
    const sqlClient = Xs(c2.env.NEON_DATABASE_URL);
    const rows = await sqlClient(`SELECT value FROM settings WHERE key = 'apps_cache'`);
    if (rows.length > 0) return c2.json(JSON.parse(rows[0].value));
  } catch {
  }
  return c2.json([], 200);
});
